def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([30]), fmt([7]), fmt([5, 5]), fmt([2, 3, 5]), fmt([2, 4, 8, 16]), fmt([1, 1, 1]),
             fmt([30, 1]), fmt([29, 30, 28])]
    for n in (2, 3, 4, 5, 8, 12, 20, 40):
        for vmax in (6, 30):
            tests.append(fmt([rng.randint(1, vmax) for _ in range(n)]))
    for _ in range(4):
        base = rng.choice([2, 3, 4, 6])
        tests.append(fmt([base * rng.randint(1, 30 // base) for _ in range(rng.randint(5, 30))]))
    N = 10 ** 5
    tests.append(fmt([rng.randint(1, 30) for _ in range(N)]))
    tests.append(fmt([30] * N))
    tests.append(fmt([rng.choice([6, 12, 18, 24, 30]) for _ in range(N)]))
    tests.append(fmt([rng.choice([1, 29, 23, 19, 17, 30]) for _ in range(N)]))
    return tests
